@Test
public void testDiskQueue() throws Exception {
    DiskQueue<IntWritable> queue = getQueue();
    checkQueue(queue);
    queue.close();
}

@Test
public void testMultipleIterations() throws Exception {
    DiskQueue<IntWritable> queue = getQueue();
    for (int superstep = 0; superstep < 15; superstep++) {
        checkQueue(queue);
    }
    queue.close();
}

